```cpp
#include <meta>

using namespace std::meta;

template <auto>
struct sfinae_probe_value
{
};

template <std::meta::info Refl>
concept ClosureType = std::meta::is_type(Refl) &&
    !std::meta::is_union_type(Refl) && !std::meta::is_aggregate_type(Refl) &&
    std::meta::is_class_type(Refl) && !std::meta::has_identifier(Refl);

template <std::meta::info Refl>
    requires ClosureType<Refl>
consteval auto extract_closure_invoke_operator_refl()
{
    constexpr auto closure_type_refl = Refl;
    using closure_t                  = typename[:closure_type_refl:];
    // this might be a function or function template, but a closure type can
    // only have exactly one of it so it must be callable.
    return ^^closure_t::operator(); // what is overloaded?
}

template <std::meta::info Refl>
consteval auto emit_members()
{
    constexpr auto ctx = access_context::unchecked();
    template for(constexpr auto m : std::define_static_array(members_of(Refl, ctx)))
    {
        static_assert(false, display_string_of(m));
    }
}

template <std::meta::info Refl, std::meta::operators Op>
concept OperatorFunctionOrTemplateOf = requires {
    typename sfinae_probe_value<std::meta::operator_of(Refl)>;
} && std::meta::operator_of(Refl) == Op;

template <std::meta::info Func>
concept IsClosureTypeCallOperator = std::meta::is_class_member(Func) &&
    OperatorFunctionOrTemplateOf<Func, std::meta::op_parentheses> &&
    requires {
        typename sfinae_probe_value<
            extract_closure_invoke_operator_refl<std::meta::parent_of(Func)>()
        >;
    } &&
    extract_closure_invoke_operator_refl<std::meta::parent_of(Func)>() == Func;

void func() {}

consteval
{
    constexpr auto refl_l_d_auto = ^^decltype([](this auto &&) { })::operator();
    constexpr auto refl_l = ^^decltype([]() { })::operator();
    emit_members<dealias(parent_of(refl_l_d_auto))>();
    static_assert(!IsClosureTypeCallOperator<^^func>);
    static_assert(IsClosureTypeCallOperator<refl_l>); // no `this auto` -> pass
    // this line should not fail during SFINAE
    static_assert(IsClosureTypeCallOperator<refl_l_d_auto>); // `this auto` -> fail
}
