    s3(double i) {}
};

template <info Func>
consteval void emit_params()
{
    template for(constexpr auto p : std::define_static_array(parameters_of(Func)))
    {
        static_assert(false, string_view("param:"));
        static_assert(false, display_string_of(type_of(p)));
    }
}

template <info Refl> requires (is_class_type(Refl))
consteval void emit_ctor_params()
{
    static_assert(false, display_string_of(Refl));
    constexpr auto ctx = access_context::current();
    template for(constexpr auto m : std::define_static_array(members_of(Refl, ctx)))
    {
        if constexpr(is_constructor(m))
        {
            emit_params<m>();
        }
    }
}

consteval
{
    // default/copy/move ctors and ctors with params all correctly considered. 
    emit_ctor_params<^^s>();
    emit_ctor_params<^^s2>();
    emit_ctor_params<^^s3>();
    // correct.
    emit_params<^^s::func3>();
    // bug: can't `parameters_of` a constructor regardless
    // whether it's overloaded when it is not obtained
    // via `members_of`
    emit_params<^^s2::s2>();
    emit_params<^^s::s>();
    // bug should error
    static_assert(^^s::s != info {});
    // correct
    static_assert(^^s::func2 != info {});
    // correct error message on overloaded functions
    static_assert(^^s::func != info {});
}
```

