Currently I have tested

```cpp
#include <meta>

using t1 = int;

namespace refl::tests
{
template <auto Val>
struct s
{
    constexpr static std::meta::info val = Val;
};

using t2 = int;

// clang-format off
struct s1
{
    using t3 = int;
    auto mem_func(int) { return 0; }
    static auto mem_func2(...) { return 0; }
};

// clang-format on

enum e
{
    e1,
};

struct s2 : s1
{
};

void func()
{
}

auto func1()
{
}

template <typename>
auto template_func()
{
}

struct tbd;

// clang-format off
[[=1]] void f();
// clang-format on

consteval
{
    constexpr auto rn = std::meta::info { };
    // null
    static_assert(s<rn>::val == rn);
    // type
    constexpr auto rt = ^^int;
    static_assert(s<rt>::val == ^^int);
#if __has_feature(entity_proxy_reflection)
    #define dealias underlying_entity_of
    // type alias
    constexpr auto rt_alias = ^^int32_t;
    static_assert(std::meta::dealias(s<rt_alias>::val) == ^^int);
    // type alias (unqualified)
    constexpr auto rt_alias_uq = ^^t1;
    static_assert(std::meta::dealias(s<rt_alias_uq>::val) == ^^int);
    // type alias (qualified, namespace)
    constexpr auto rt_alias_qn = ^^t2;
    static_assert(std::meta::dealias(s<rt_alias_qn>::val) == ^^int);
    // type alias (qualified, class)
    constexpr auto rt_alias_qc = ^^s1::t3;
    static_assert(std::meta::dealias(s<rt_alias_qc>::val) == ^^int);
#endif
    // object
    constexpr static int i  = 0;
    constexpr auto       ro = std::meta::reflect_object(i);
    static_assert(s<ro>::val != rn);
    // value
    constexpr auto rv = std::meta::reflect_constant(1);
    static_assert(s<rv>::val != rn);
    // function (free)
    constexpr auto rf_free = ^^func;
    static_assert(s<rf_free>::val == ^^func);
    // function (free, deduced type)
    constexpr auto rf_free_deduced = ^^func1;
    static_assert(s<rf_free_deduced>::val == ^^func1);
    // function (class member)
    constexpr auto rf_class_member = ^^s1::mem_func;
    static_assert(s<rf_class_member>::val == ^^s1::mem_func);
    // function (static class member)
    constexpr auto rf_class_member_static = ^^s1::mem_func2;
    static_assert(s<rf_class_member_static>::val == ^^s1::mem_func2);
    // function (lambda call operator)
    constexpr auto l               = [](int) { };
    constexpr auto rf_closure_call = ^^decltype(l)::operator();
    static_assert(s<rf_closure_call>::val == ^^decltype(l)::operator());
    // value declaration
    [[maybe_unused]]
    constexpr auto val         = false;
    constexpr auto rf_decl_val = ^^val;
    static_assert(s<rf_decl_val>::val == ^^val);
    // enum declaration
    constexpr auto rf_decl_enum = ^^e;
    static_assert(s<rf_decl_enum>::val == ^^e);
    // enumerator declaration
    constexpr auto rf_decl_enum_e = ^^e::e1;
    static_assert(s<rf_decl_enum_e>::val == ^^e::e1);
    // function template (lambda call operator, deduced this)
    constexpr auto lt                   = [](this auto &&) { };
    constexpr auto rf_closure_call_auto = ^^decltype(lt)::operator();
    static_assert(s<rf_closure_call_auto>::val == ^^decltype(lt)::operator());
    // class template
    constexpr auto rt_class = ^^s;
    static_assert(s<rt_class>::val == ^^s);
    // root namespace
    constexpr auto rns_root = ^^::;
    static_assert(s<rns_root>::val == ^^::);
    // nested namespace
    constexpr auto rns_nested = ^^refl::tests;
    static_assert(s<rns_nested>::val == ^^refl::tests);
    // parameter
    constexpr auto rp = std::meta::parameters_of(^^s1::mem_func)[0];
    static_assert(std::meta::is_function_parameter(s<rp>::val));
    // base relationship
    constexpr auto ctx    = std::meta::access_context::current();
    constexpr auto r_base = std::meta::bases_of(^^s2, ctx)[0];
    // why the hell would `parent_of` return the derived type? weird proposal.
    static_assert(std::meta::parent_of(s<r_base>::val) == ^^s2);
    // data-member-spec
    constexpr auto dms = std::meta::data_member_spec(^^tbd);
    static_assert(std::meta::is_data_member_spec(s<dms>::val));
    // todo: entity proxy
    // constexpr auto rf_proxy = /* ??? */
    // static_assert(s<rf_proxy>::val == /* ??? */);
    // static_assert(std::meta::is_entity_proxy(s<rf_proxy>::val));
    // annotations
    static_assert(
        std::meta::is_annotation(s<std::meta::annotations_of(^^f)[0]>::val)
    );
}
} // namespace refl::tests
```

without crashing the compiler. Just that I am merging commits from upstream and it seems I got consteval value init somehow broken so I gotta file the PR later.

@HaydnTrigg I fixed it in https://github.com/bloomberg/clang-p2996/pull/243/commits/b725cb40f042c25e2a6d3859fdf4b1ceb8e5957a

Also thank you for your heads-up on this name mangling concern. 

It made me realize why my early code for C++ function binding ThunkGen for my scripting vm would have naming collisions:

```cpp
template <
    std::meta::info Refl, // <-- this is not mangled so it is basically left alone with the same value for all instantiations
    // These values must be constexpr so they must be put in the template args.
    bool            IsFunction = std::meta::is_function(Refl),
    bool            IsLambda   = meta::reflection::CanExtractClosureType<Refl>,
    // todo: move this to usagi::meta
    std::meta::info FuncRefl =
        [] {
            if constexpr(IsFunction)
            {
                return Refl;
            }
            else
            {
                return meta::reflection::
                    extract_closure_invoke_operator_refl<Refl>();
            }
        }(),
    // Use function address to disambiguate function linkages
    typename[:std::meta::type_of(Refl):] * = &([:Refl:]) // <-- I just worked around it without realizing it's a name mangling thing
>
    requires (IsFunction || IsLambda)
consteval std::size_t get_function_nargs()
{
    return std::meta::parameters_of(FuncRefl).size();
}
```

Related commit

https://github.com/bloomberg/clang-p2996/pull/243/commits/b725cb40f042c25e2a6d3859fdf4b1ceb8e5957a

@zebullax  this is an interesting example of how undefined behavior caused by `llvm_unreachable` can cause. So for debug builds I recommend always setting `-DLLVM_UNREACHABLE_OPTIMIZE=Off`

